import { useMemo } from 'react';

import { Training } from 'pages/trainingHub/domain';

import { useTrainingData } from '../useTrainingData';

export const useFilterTraining = (searchValue: string) => {
  const { trainingData } = useTrainingData();

  const filteredData = useMemo(() => {
    const result: Training[] = [];
    const normalizedSearchValue = searchValue.trim().toLowerCase();

    if (normalizedSearchValue.length === 0) return result;

    for (const pillar in trainingData) {
      const matchedTrainingsList = trainingData[pillar].trainings.filter(
        (training: Training) =>
          training.title.toLowerCase().includes(normalizedSearchValue) ||
          training.tags.some((tag) =>
            tag.toLowerCase().includes(normalizedSearchValue),
          ) ||
          training.description.toLowerCase().includes(normalizedSearchValue),
      );

      if (matchedTrainingsList.length > 0) {
        result.push(...matchedTrainingsList);
      }
    }
    return result;
  }, [searchValue]);

  return { filteredData };
};
